func cliArgsFromMCP(args map[string]any, blocked map[string]bool) []string {
	keys := make([]string, 0, len(args))
	for k := range args {
		if strings.Contains(k, "=") {
			continue
		}
		if blocked[k] || blockedDestinationFlags[k] {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var out []string
	for _, k := range keys {
		v := args[k]
		switch tv := v.(type) {
		case bool:
			if tv {
				out = append(out, "--"+k)
			}
		case float64:
			out = append(out, "--"+k, strconv.FormatFloat(tv, 'f', -1, 64))
		case string:
			if tv != "" {
				out = append(out, "--"+k, tv)
			}
		case []any:
			if len(tv) > 0 {
				parts := make([]string, 0, len(tv))
				for _, item := range tv {
					parts = append(parts, fmt.Sprintf("%v", item))
				}
				out = append(out, "--"+k, strings.Join(parts, ","))
			}
		default:
			if v != nil {
				out = append(out, "--"+k, fmt.Sprintf("%v", v))
			}
		}
	}
	return out
}

// SplitShellArgs whitespace-splits with shell-style quote preservation.
func SplitShellArgs(s string) []string {
	var tokens []string
	var cur []rune
	inSingleQuote := false
	inDoubleQuote := false
	escaped := false
	for _, r := range s {
		switch {
		case escaped:
			cur = append(cur, r)
			escaped = false
		case r == '\\' && !inSingleQuote:
			escaped = true
		case r == '\'' && !inDoubleQuote:
			inSingleQuote = !inSingleQuote
		case r == '"' && !inSingleQuote:
			inDoubleQuote = !inDoubleQuote
		case (r == ' ' || r == '\t') && !inSingleQuote && !inDoubleQuote:
			if len(cur) > 0 {
				tokens = append(tokens, string(cur))
				cur = cur[:0]
			}
		default:
			cur = append(cur, r)
		}
	}
	if escaped {
		cur = append(cur, '\\')
	}
	if len(cur) > 0 {
		tokens = append(tokens, string(cur))
	}
	return tokens
}

// RunCLICommand executes the companion CLI while preserving stdout as the
// machine-readable channel. Stderr is included only in error text so post-run
// telemetry or quota output cannot corrupt JSON results.
func RunCLICommand(ctx context.Context, binPath string, args []string) (string, error) {
	cmd := exec.CommandContext(ctx, binPath, args...) // #nosec G204 -- trusted companion CLI path, args pre-tokenized.
	stdout := newCappedCapture()
	stderr := newCappedCapture()
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	err := cmd.Run()
	stdoutText := stdout.String()
	if err != nil {
		stderrText := strings.TrimSpace(stderr.String())
		msg := stderrText
		if msg == "" {
			msg = strings.TrimSpace(stdoutText)
		}
		if msg != "" {
			label := "stderr"
			if stderrText == "" {
				label = "output"
			}
			return stdoutText, fmt.Errorf("cli %s: %w (%s: %s)", binPath, err, label, bound.Text(msg))
		}
		return stdoutText, fmt.Errorf("cli %s: %w", binPath, err)
	}
	return stdoutText, nil
}
